package dev.reliefgrid;
import com.fasterxml.jackson.databind.ObjectMapper;import dev.reliefgrid.repo.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:reliefgridtest;DB_CLOSE_DELAY=-1","spring.h2.console.enabled=false"}) @AutoConfigureMockMvc class ApiIntegrationTest {
 @Autowired MockMvc mvc; @Autowired ObjectMapper objectMapper;@Autowired AssignmentRepository assignments;@Autowired ResourceStockRepository stocks;
 @Test void inventoryAndApprovalFlow()throws Exception{mvc.perform(get("/api/shelters")).andExpect(status().isOk());int before=stocks.findAll().stream().mapToInt(s->s.available).sum();String plan=mvc.perform(post("/api/plans").header("X-Admin-Key","local-demo-admin")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();long id=objectMapper.readTree(plan).get("id").asLong();assertEquals(before,stocks.findAll().stream().mapToInt(s->s.available).sum());mvc.perform(post("/api/plans/"+id+"/approve").header("X-Admin-Key","local-demo-admin")).andExpect(status().isOk());assertTrue(stocks.findAll().stream().mapToInt(s->s.available).sum()<=before);mvc.perform(post("/api/plans/"+id+"/approve").header("X-Admin-Key","local-demo-admin")).andExpect(status().isConflict());}
 @Test void idempotentSyncAndConflict()throws Exception{String a="[{\"key\":\"test-sync-key\",\"request\":{\"shelterId\":1,\"category\":\"WATER\",\"quantity\":3,\"urgency\":4}}]";String b=a.replace("\"quantity\":3","\"quantity\":4");mvc.perform(post("/api/sync").contentType(MediaType.APPLICATION_JSON).content(a)).andExpect(status().isOk()).andExpect(jsonPath("$[0].status").value("CREATED"));mvc.perform(post("/api/sync").contentType(MediaType.APPLICATION_JSON).content(a)).andExpect(jsonPath("$[0].status").value("REPLAY"));mvc.perform(post("/api/sync").contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(jsonPath("$[0].status").value("CONFLICT"));}
 @Test void rejectsUnprivilegedApproval()throws Exception{mvc.perform(post("/api/plans")).andExpect(status().isForbidden());}
}
